### Role-Based Access Control (RBAC) for Tools

Authentication answers "who are you?" Authorization answers "what are you allowed to do?" RBAC is the most common authorization pattern:

```python
from enum import Enum
from typing import Set, Dict, List, Optional
from dataclasses import dataclass

class UserRole(Enum):
    ADMIN = "admin"
    DEVELOPER = "developer"
    USER = "user"
    GUEST = "guest"

@dataclass
class UserContext:
    """Represents the authenticated user context for an agent session."""
    user_id: str
    role: UserRole
    org_id: str
    permissions_override: Optional[Set[str]] = None

class ToolACL:
    """Access Control List for agent tools — default deny policy."""

    # Which roles can use which tools
    TOOL_PERMISSIONS: Dict[str, Set[UserRole]] = {
        "search_database": {UserRole.ADMIN, UserRole.DEVELOPER, UserRole.USER},
        "get_record": {UserRole.ADMIN, UserRole.DEVELOPER, UserRole.USER},
        "delete_record": {UserRole.ADMIN},
        "bulk_delete": {UserRole.ADMIN},
        "write_file": {UserRole.ADMIN, UserRole.DEVELOPER},
        "read_file": {UserRole.ADMIN, UserRole.DEVELOPER, UserRole.USER},
        "send_email": {UserRole.ADMIN, UserRole.DEVELOPER},
        "execute_code": {UserRole.ADMIN, UserRole.DEVELOPER},
        "manage_users": {UserRole.ADMIN},
        "view_analytics": {UserRole.ADMIN, UserRole.DEVELOPER},
        "read_public_data": {UserRole.ADMIN, UserRole.DEVELOPER, UserRole.USER, UserRole.GUEST},
    }

    # Action-level permissions per role
    ROLE_ACTIONS: Dict[UserRole, Set[str]] = {
        UserRole.ADMIN: {"read", "write", "delete", "execute", "admin"},
        UserRole.DEVELOPER: {"read", "write", "execute"},
        UserRole.USER: {"read", "execute"},
        UserRole.GUEST: {"read"},
    }

    def can_execute_tool(self, tool_name: str, user: UserContext) -> bool:
        """Check if the user's role permits executing a specific tool."""
        # Check permission overrides first
        if user.permissions_override is not None:
            return tool_name in user.permissions_override

        # Default deny: if tool not in ACL, it's blocked
        if tool_name not in self.TOOL_PERMISSIONS:
            return False

        return user.role in self.TOOL_PERMISSIONS[tool_name]

    def can_perform_action(self, action: str, user: UserContext) -> bool:
        """Check if the user's role permits a specific action type."""
        allowed = self.ROLE_ACTIONS.get(user.role, set())
        return action in allowed

    def get_allowed_tools(self, user: UserContext) -> List[str]:
        """Return the list of tools this user is allowed to execute."""
        if user.permissions_override is not None:
            return sorted(user.permissions_override)

        return sorted(
            tool for tool, roles in self.TOOL_PERMISSIONS.items()
            if user.role in roles
        )

# Usage
acl = ToolACL()
admin_user = UserContext(user_id="alice", role=UserRole.ADMIN, org_id="acme")
guest_user = UserContext(user_id="bob", role=UserRole.GUEST, org_id="acme")

print(f"Admin can delete: {acl.can_execute_tool('delete_record', admin_user)}")
print(f"Guest can delete: {acl.can_execute_tool('delete_record', guest_user)}")
print(f"Guest tools: {acl.get_allowed_tools(guest_user)}")
# Output:
# Admin can delete: True
# Guest can delete: False
# Guest tools: ['read_public_data']
```

### Authorization Middleware for Tool Calls

Wrap every tool invocation with an authorization check:

```python
from functools import wraps
from typing import Any, Callable

class UnauthorizedToolCall(Exception):
    """Raised when a tool call fails authorization."""
    def __init__(self, tool_name: str, user_id: str, reason: str):
        self.tool_name = tool_name
        self.user_id = user_id
        self.reason = reason
        super().__init__(
            f"User '{user_id}' is not authorized to call '{tool_name}': {reason}"
        )

def require_role(*roles: UserRole):
    """Decorator that enforces role-based access on a tool function."""
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, user_context: UserContext = None, **kwargs):
            if user_context is None:
                raise UnauthorizedToolCall(
                    func.__name__, "unknown",
                    "No user context provided"
                )
            if user_context.role not in roles:
                raise UnauthorizedToolCall(
                    func.__name__, user_context.user_id,
                    f"Requires one of: {[r.value for r in roles]}"
                )
            return func(*args, user_context=user_context, **kwargs)
        wrapper._required_roles = roles
        return wrapper
    return decorator

def require_permission(*permissions: str):
    """Decorator that enforces action-level permissions."""
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, user_context: UserContext = None, **kwargs):
            if user_context is None:
                raise UnauthorizedToolCall(
                    func.__name__, "unknown", "No user context provided"
                )
            acl = ToolACL()
            for perm in permissions:
                if not acl.can_perform_action(perm, user_context):
                    raise UnauthorizedToolCall(
                        func.__name__, user_context.user_id,
                        f"Missing permission: {perm}"
                    )
            return func(*args, user_context=user_context, **kwargs)
        return wrapper
    return decorator

# Example: protected tool definitions
@require_role(UserRole.ADMIN)
def delete_all_records(user_context: UserContext, table_name: str) -> dict:
    return {"status": "deleted", "table": table_name, "by": user_context.user_id}

@require_role(UserRole.ADMIN, UserRole.DEVELOPER)
def execute_code(user_context: UserContext, code: str) -> dict:
    return {"status": "executed", "result": "42"}

@require_permission("read")
def read_file(user_context: UserContext, path: str) -> dict:
    return {"status": "ok", "content": "file contents here"}

# Test
try:
    guest = UserContext(user_id="bob", role=UserRole.GUEST, org_id="acme")
    delete_all_records(user_context=guest, table_name="users")
except UnauthorizedToolCall as e:
    print(f"Blocked: {e}")
```

### Authorization Patterns Compared

| Pattern | Description | Pros | Cons |
|---|---|---|---|
| **Whitelist** | Only explicitly listed tools are callable | Secure by default | Must update list when adding tools |
| **Blacklist** | All tools callable except blocked ones | Easy to set up | Insecure — new dangerous tools are allowed by default |
| **Capability-based** | Tools declare required capabilities; agents must possess them | Fine-grained, composable | More complex to implement |
| **Context-based** | Authorization depends on runtime context (time, IP, resource ownership) | Flexible, powerful | Hard to test exhaustively |

**Always use a whitelist approach in production.** Blacklists are fundamentally insecure for agentic systems because the LLM can discover and exploit tools you forgot to block.

### Capability-Based Authorization

For finer control, use a capability-based system where each tool declares what it needs:

```python
@dataclass
class ToolCapability:
    """Declares what a tool requires to execute."""
    name: str
    required_permissions: Set[str]
    required_roles: Set[UserRole] = None
    resource_type: str = None  # e.g., "database", "file_system", "email"
    max_impact: str = "low"  # low, medium, high, critical

class CapabilityAuthorizer:
    """Authorizes tools based on their declared capabilities."""

    def __init__(self):
        self.tool_capabilities: Dict[str, ToolCapability] = {}

    def register_tool(self, capability: ToolCapability):
        """Register a tool's capability requirements."""
        self.tool_capabilities[capability.name] = capability

    def authorize(
        self, tool_name: str, user: UserContext, context: dict = None
    ) -> tuple[bool, str]:
        """Check if a tool call is authorized. Returns (allowed, reason)."""
        cap = self.tool_capabilities.get(tool_name)
        if not cap:
            return False, f"Tool '{tool_name}' is not registered"

        # Check role
        if cap.required_roles and user.role not in cap.required_roles:
            return False, (
                f"Role '{user.role.value}' not in required roles: "
                f"{[r.value for r in cap.required_roles]}"
            )

        # Check permissions
        acl = ToolACL()
        for perm in cap.required_permissions:
            if not acl.can_perform_action(perm, user):
                return False, f"Missing permission: {perm}"

        # Context-based checks (e.g., business hours, IP allowlist)
        if context and not self._check_context(cap, user, context):
            return False, "Context-based authorization failed"

        return True, "Authorized"

    def _check_context(
        self, cap: ToolCapability, user: UserContext, context: dict
    ) -> bool:
        """Example context-based rules."""
        # Critical tools can only be called during business hours
        if cap.max_impact == "critical":
            hour = context.get("hour", 0)
            if not (9 <= hour <= 17):
                return False

        # Resource ownership check
        if cap.resource_type == "file_system":
            requested_path = context.get("path", "")
            if not requested_path.startswith(f"/users/{user.user_id}/"):
                return False

        return True

# Register tools with their capability declarations
authorizer = CapabilityAuthorizer()
authorizer.register_tool(ToolCapability(
    name="delete_record",
    required_permissions={"delete"},
    required_roles={UserRole.ADMIN},
    resource_type="database",
    max_impact="high",
))
authorizer.register_tool(ToolCapability(
    name="read_file",
    required_permissions={"read"},
    resource_type="file_system",
    max_impact="low",
))
authorizer.register_tool(ToolCapability(
    name="purge_database",
    required_permissions={"delete", "admin"},
    required_roles={UserRole.ADMIN},
    resource_type="database",
    max_impact="critical",
))

# Authorize calls
dev_user = UserContext(user_id="carol", role=UserRole.DEVELOPER, org_id="acme")
allowed, reason = authorizer.authorize("read_file", dev_user, {"path": "/users/carol/doc.txt"})
print(f"read_file for carol: {allowed} — {reason}")

allowed, reason = authorizer.authorize("delete_record", dev_user)
print(f"delete_record for carol: {allowed} — {reason}")

admin_user = UserContext(user_id="alice", role=UserRole.ADMIN, org_id="acme")
allowed, reason = authorizer.authorize("purge_database", admin_user, {"hour": 10})
print(f"purge_database during business hours: {allowed} — {reason}")

allowed, reason = authorizer.authorize("purge_database", admin_user, {"hour": 22})
print(f"purge_database at 10pm: {allowed} — {reason}")
```
